package com.hemopharm.backend.service;

import com.hemopharm.backend.model.BloodTest;
import com.hemopharm.backend.model.BloodTestResult;

import java.util.List;

public interface ReportExtractionService {

    List<BloodTestResult> extractResults(Long bloodTestId, byte[] content);

    /**
     * Extracts a report into a brand-new blood test whose id is generated by the database.
     *
     * @param userId optional owner; the first user is used when null
     */
    BloodTest extractNewReport(byte[] content, String fileName, Long userId);
}
